/// 验证握手建立后双向帧回环：client→host 与 host→client 各发一条
/// 消息，对端都能解出原文。
#[tokio::test]
async fn round_trips_frames_in_both_directions_after_handshake() {
    let (host_secret, host_public) = generate_ecdh_key_pair().expect("host keypair");
    let host_pub_jwk = export_public_key_jwk(&host_public);
    let mut host = HostHandshake::new(host_secret);
    let nonce = generate_handshake_nonce().expect("nonce");
    let mut client = test_client(&host_pub_jwk, nonce).await;

    let action = host.handle_text(&client.hello_text);
    let HandshakeAction::Established {
        channel: mut host_channel,
        ..
    } = action
    else {
        panic!("expected established");
    };

    let c2h = client
        .encryptor
        .encrypt(b"client-to-host payload")
        .expect("encrypt");
    assert_eq!(
        host_channel.decryptor.decrypt(&c2h).expect("decrypt"),
        b"client-to-host payload"
    );

    let h2c = host_channel
        .encryptor
        .encrypt(b"host-to-client payload")
        .expect("encrypt");
    assert_eq!(
        client.decryptor.decrypt(&h2c).expect("decrypt"),
        b"host-to-client payload"
    );
}

/// 生成随机 256 位 AES-GCM 密钥，供无需 pinned 输入的帧加密测试使用。
fn random_aes_key() -> Aes256Gcm {
    let mut bytes = [0u8; 32];
    rand::fill(&mut bytes);
    Aes256Gcm::new(AesKey::<Aes256Gcm>::from_slice(&bytes))
}

/// 验证 AES-GCM 完整性保护：篡改密文最后一字节后解密失败，错误串为
/// "frame decryption failed"。
#[test]
fn rejects_tampered_ciphertext() {
    let key = random_aes_key();
    let mut enc = FrameEncryptor::with_prefix(key.clone(), [0; 4]);
    let mut dec = FrameDecryptor::new(key);
    let mut frame = enc.encrypt(&[1, 2, 3]).expect("encrypt");
    let last = frame.len() - 1;
    frame[last] ^= 0xff;
    assert_eq!(
        dec.decrypt(&frame).unwrap_err().0,
        "frame decryption failed"
    );
}

/// 验证反重放：同一帧重放（计数器未严格递增）被拒绝，错误串
/// "frame counter regression"。
#[test]
fn rejects_counter_regression_or_replay() {
    let key = random_aes_key();
    let mut enc = FrameEncryptor::with_prefix(key.clone(), [0; 4]);
    let mut dec = FrameDecryptor::new(key);
    let first = enc.encrypt(&[9]).expect("encrypt");
    dec.decrypt(&first).expect("first");
    // Replaying the same frame (counter no longer strictly increasing) fails.
    assert_eq!(
        dec.decrypt(&first).unwrap_err().0,
        "frame counter regression"
    );
}

/// 验证畸形帧被拒：过短帧报 "encrypted frame too short"，版本号非 1
/// 报 "unsupported encrypted frame version"。
#[test]
fn rejects_short_frames_and_wrong_version() {
    let key = random_aes_key();
    let mut dec = FrameDecryptor::new(key);
    assert_eq!(
        dec.decrypt(&[1u8; 10]).unwrap_err().0,
        "encrypted frame too short"
    );
    let mut frame = vec![2u8];
    frame.extend_from_slice(&[0u8; 12]);
    frame.extend_from_slice(&[0u8; 16]);
    assert_eq!(
        dec.decrypt(&frame).unwrap_err().0,
        "unsupported encrypted frame version"
    );
}

/// 验证 ready 之后收到明文帧一律 fail-closed：以 1011
/// "plaintext frame on established channel" 关闭连接。
#[tokio::test]
async fn fails_closed_on_plaintext_after_ready() {
    let (host_secret, host_public) = generate_ecdh_key_pair().expect("host keypair");
    let host_pub_jwk = export_public_key_jwk(&host_public);
    let mut host = HostHandshake::new(host_secret);
    let nonce = generate_handshake_nonce().expect("nonce");
    let mut client = test_client(&host_pub_jwk, nonce).await;
    host.handle_text(&client.hello_text);
    match host.handle_text("{\"hello\":\"not a handshake\"}") {
        HandshakeAction::Fail { close_code, reason } => {
            assert_eq!(close_code, 1011);
            assert_eq!(reason, "plaintext frame on established channel");
        }
        _ => panic!("expected fail-closed"),
    }
}

/// 验证 ready 之前的非 hello 明文（垃圾文本、协议版本不为 1 的 hello）
/// 被静默忽略（Ignore），不会导致失败。
#[tokio::test]
async fn non_hello_plaintext_before_ready_is_ignored() {
    let (host_secret, _) = generate_ecdh_key_pair().expect("host keypair");
    let mut host = HostHandshake::new(host_secret);
    assert!(matches!(
        host.handle_text("garbage"),
        HandshakeAction::Ignore
    ));
    // Wrong protocol version is not a hello either.
    assert!(matches!(
        host.handle_text("{\"t\":\"hello\",\"v\":2}"),
        HandshakeAction::Ignore
    ));
}

/// 验证字段不合法的 hello（公钥坐标无法解码）fail-closed：1011
/// "malformed hello"。
#[tokio::test]
async fn malformed_hello_fails_closed() {
    let (host_secret, host_public) = generate_ecdh_key_pair().expect("host keypair");
    let host_pub_jwk = export_public_key_jwk(&host_public);
    let mut host = HostHandshake::new(host_secret);
    let hello = serde_json::to_string(&json!({
        "t": "hello",
        "v": 1,
        "clientPubJwk": { "kty": "EC", "crv": "P-256", "x": "AAAA", "y": "AAAA" },
        "nonce": "AAAA",
    }))
    .unwrap_or_default();
    match host.handle_text(&hello) {
        HandshakeAction::Fail { close_code, reason } => {
            assert_eq!(close_code, 1011);
            assert_eq!(reason, "malformed hello");
        }
        _ => panic!("expected malformed hello failure"),
    }
    let _ = host_pub_jwk;
}

/// 验证 base64url 编解码双向 round-trip 与 JS pinned 向量一致，
/// 且拒绝非法输入（奇数长度、含 = 或空格）。
#[test]
fn base64url_helpers_round_trip_and_match_pinned_vectors() {
    // Pinned from the JS implementation.
    let vectors: [(&str, &str); 6] = [
        ("", ""),
        ("00", "AA"),
        ("0001", "AAE"),
        ("000102", "AAEC"),
        ("fafbfcfdfeff", "-vv8_f7_"),
        ("61", "YQ"),
    ];
    for (hex, b64) in vectors {
        let bytes = hex_to_bytes(hex);
        assert_eq!(bytes_to_base64_url(&bytes), b64, "encode {hex}");
        assert_eq!(
            base64_url_to_bytes(b64).expect("decode"),
            bytes,
            "decode {b64}"
        );
    }
    assert!(base64_url_to_bytes("A").is_err());
    assert!(base64_url_to_bytes("a=b").is_err());
    assert!(base64_url_to_bytes("AB CD").is_err());
}

/// 验证公钥/私钥 JWK 导入导出 round-trip；曲线外的点像 WebCrypto
/// importKey 一样被拒绝。
#[test]
fn jwk_import_export_round_trip() {
    let (secret, public) = generate_ecdh_key_pair().expect("keypair");
    let jwk = export_public_key_jwk(&public);
    let reimported = import_ecdh_public_key(&jwk).expect("reimport");
    assert_eq!(
        reimported.to_encoded_point(false),
        public.to_encoded_point(false)
    );
    // A point off the curve is rejected like WebCrypto importKey.
    let bad = json!({
        "kty": "EC", "crv": "P-256",
        "x": bytes_to_base64_url(&[0xff; 32]),
        "y": bytes_to_base64_url(&[0xff; 32]),
    });
    assert!(import_ecdh_public_key(&bad).is_err());
    // Private import round-trips through the JWK d.
    let private_jwk = json!({
        "kty": "EC", "crv": "P-256",
        "x": jwk["x"], "y": jwk["y"],
        "d": bytes_to_base64_url(&secret.to_bytes()),
    });
    let reimported_secret = import_ecdh_private_key(&private_jwk).expect("private");
    assert_eq!(reimported_secret.to_bytes(), secret.to_bytes());
}

